  const daysUntil=value=>value?Math.ceil((Date.parse(String(value).slice(0,10)+'T00:00:00Z')-Date.parse(dateOffset(0)+'T00:00:00Z'))/86400000):Infinity;
  const deadlineText=(value,prefix='Due')=>{const n=daysUntil(value);return !Number.isFinite(n)?'No deadline':n<0?`${prefix==='Expires'?'Expired':'Overdue by'} ${Math.abs(n)} ${Math.abs(n)===1?'day':'days'}${prefix==='Expires'?' ago':''}`:n===0?`${prefix} today`:n===1?`${prefix} tomorrow`:`${prefix} in ${n} days`;};
  const expiredQuote=q=>!['Accepted','Rejected'].includes(q.status)&&daysUntil(q.expiry)<0;
  const metric=(label,value,detail)=>`<div class="metric"><div class="metric-top">${esc(label)}</div><div class="metric-value">${value}</div><div class="metric-foot">${esc(detail)}</div></div>`;
