  function activityTimeline(events){return events.length?`<ol class="activity-timeline">${events.map(e=>`<li><span class="timeline-dot"></span><div><strong>${esc(activityNames[e.type]||e.action||'Quote activity')}</strong><p>${esc(e.metadata?.message||e.number||e.object||'')}</p><time>${new Date(e.createdAt||e.at).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div></li>`).join('')}</ol>`:'<div class="quiet-state"><h3>Activity will appear here.</h3><p>Customer responses and quote milestones keep you informed.</p></div>';}
  function lineResult(i,currency){const revenue=Number(i.price)*Number(i.qty),margin=Number(i.price)?(Number(i.price)-Number(i.cost))/Number(i.price)*100:0;return `<strong>${money(revenue,currency)}</strong><small class="${margin<Number(db.settings.margin??20)?'text-warning':''}">${margin.toFixed(1)}% margin</small>${i.minimumPrice!=null&&Number(i.price)<Number(i.minimumPrice)?'<small class="text-warning">Below minimum</small>':''}`;}
  function commercialSummary(q){const m=quoteMath(q),target=Number(db.settings.margin??20),under=m.margin<target;return `<div class="eyebrow">COMMERCIAL PREVIEW</div><div class="sum-row"><span>Gross subtotal</span><strong>${money(m.subtotal+m.discount,q.currency)}</strong></div><div class="sum-row"><span>Discount</span><strong>− ${money(m.discount,q.currency)}</strong></div><div class="sum-row"><span>Net subtotal</span><strong>${money(m.subtotal,q.currency)}</strong></div><div class="sum-row"><span>Tax</span><strong>${money(m.tax,q.currency)}</strong></div><div class="summary-total"><span>Quotation total</span><strong>${money(m.total,q.currency)}</strong></div><div class="profitability"><div class="eyebrow">PROFITABILITY · INTERNAL ONLY</div><div class="sum-row"><span>Cost</span><strong>${money(m.cost,q.currency)}</strong></div><div class="sum-row"><span>Gross profit</span><strong>${money(m.profit,q.currency)}</strong></div><div class="margin-reading ${under?'text-warning':''}"><strong>${m.margin.toFixed(1)}<small>%</small></strong><span>${under?'Below target':'At or above target'}<small>Target ${target}% · ${(m.margin-target).toFixed(1)} pts</small></span></div></div><p class="commercial-notice ${under?'warning':''}">${under?'Review your pricing against the commercial policy before sending.':'Review the offer, then save for server validation.'}</p><div class="summary-actions"><button class="btn primary" data-action="save-quote">Save quotation</button>${q.id?'<button class="btn" data-action="preview-draft">View saved quote</button><button class="btn" data-action="draft-followup">Draft follow-up</button>':''}${q.id&&account?'<button class="btn" data-action="ai-summarize-quote">Summarize with AI</button>':''}</div><p class="context-note">Preview only. The server validates prices, currency and approval requirements on save.</p>`;}
  function commercialOverview(q){const m=quoteMath(q);return `<div class="metric-grid commercial-metrics quote-overview">${metric('Customer total',money(q.snapshot?.totals?.total??m.total,q.currency),`Version ${q.snapshot?.version||q.version||1}`)}${metric('Cost',money(m.cost,q.currency),'Internal commercial information')}${metric('Gross profit',money(m.profit,q.currency),'Net value less cost')}${metric('Gross margin',m.margin.toFixed(1)+'%',`Target ${db.settings.margin??20}%`)}</div>${q.sourceQuoteId?`<p class="context-note">Based on <button class="text-link" data-open-quote="${esc(q.sourceQuoteId)}">${esc(getQuote(q.sourceQuoteId)?.number||'a prior quotation')}</button>. The original customer document is preserved.</p>`:''}`;}
  function updateCommercialPreview(){if(!quoteDraft)return;const target=document.getElementById('commercial-summary');if(target)target.innerHTML=commercialSummary(quoteDraft);quoteDraft.items.forEach((item,i)=>{const cell=document.getElementById('line-result-'+i);if(cell)cell.innerHTML=lineResult(item,quoteDraft.currency);});}
  function enhanceControls(){document.querySelectorAll('input.search:not([aria-label])').forEach(el=>el.setAttribute('aria-label',el.placeholder||'Search'));document.querySelectorAll('select:not([aria-label])').forEach(el=>{if(!document.querySelector('label[for="'+el.id+'"]'))el.setAttribute('aria-label','Filter records');});document.querySelectorAll('tr[data-product-edit],tr[data-open-quote],tr[data-open-rfq],tr[data-open-customer]').forEach(el=>{el.tabIndex=0;el.setAttribute('role','button');});}
  function quickCreate(){showModal('Create something new',`<div class="action-menu">${[['new-rfq','RFQ','Capture a customer request'],['new-quote','Quotation','Price a new offer'],['new-customer','Customer','Add a business contact'],...(canManage()?[['new-product','Catalog item','Build your pricing library']]:[]),['new-followup','Follow-up','Remember the next conversation']].map(([action,title,desc])=>`<button data-action="${action}" class="menu-option"><strong>${title}</strong><small>${desc}</small><span>→</span></button>`).join('')}</div>`);}
  function workspaceMenu(){showModal('Choose workspace',account?`<div class="action-menu">${(account.memberships||[{organizationId:account.organization.id,name:account.organization.name,role:account.role}]).map(m=>`<button class="menu-option" data-workspace="${esc(m.organizationId)}" ${m.organizationId===account.organization.id?'disabled':''}><strong>${esc(m.name)}</strong><small>${roleLabel(m.role)}${m.organizationId===account.organization.id?' · Current workspace':''}</small></button>`).join('')}</div>`:'<p>This is an isolated fictional workspace. Sign in to work with your organization’s records.</p>',!account?'<a class="btn primary" href="/login">Sign in</a>':'');}
  function commandSearch(){showModal('Search your workspace','<label class="sr-only" for="command-query">Search records and actions</label><input class="search command-input" id="command-query" placeholder="Quote number, customer, SKU or action…" autocomplete="off"/><div id="command-results" class="action-menu"></div>');renderCommands('');document.getElementById('command-query').focus();}
  let commandResults=[];
  function renderCommands(query){const term=query.toLowerCase();commandResults=[...db.quotes.map(q=>({label:q.number+' · '+q.title,detail:customerName(q.customerId),kind:'quote',id:q.id})),...db.rfqs.map(r=>({label:r.number+' · '+r.title,detail:'RFQ',kind:'rfq',id:r.id})),...db.customers.map(c=>({label:c.name,detail:'Customer',kind:'customer',id:c.id})),...db.products.map(p=>({label:p.name+' · '+(p.sku||''),detail:'Catalog',kind:'product',id:p.id})),...navItems.map(([p])=>({label:'Go to '+pageLabel(p),detail:'Navigation',kind:'page',id:p})),...(canWrite()?[{label:'New quotation',detail:'Create',kind:'action',id:'new-quote'},{label:'New RFQ',detail:'Create',kind:'action',id:'new-rfq'},{label:'New customer',detail:'Create',kind:'action',id:'new-customer'}]:[])].filter(r=>(r.label+' '+r.detail).toLowerCase().includes(term)).slice(0,15);document.getElementById('command-results').innerHTML=commandResults.length?commandResults.map((r,i)=>`<button class="menu-option" data-command="${i}"><strong>${esc(r.label)}</strong><small>${esc(r.detail)}</small><span>↗</span></button>`).join(''):'<p class="quiet-state">No results. Try a customer name, quote number or SKU.</p>';}
  function catalogSearch(){showModal('Add a catalog item','<label class="sr-only" for="catalog-query">Search catalog</label><input class="search command-input" id="catalog-query" placeholder="Search by name, SKU or category…"/><div id="catalog-results" class="action-menu"></div>','<button class="btn" data-action="add-quote-item">Add manual item</button>');renderCatalogResults('');document.getElementById('catalog-query').focus();}
  function renderCatalogResults(query){document.getElementById('catalog-results').innerHTML=db.products.filter(p=>p.active!==false&&(p.name+' '+p.sku+' '+p.category).toLowerCase().includes(query.toLowerCase())).map(p=>`<button class="menu-option" data-select-product="${esc(p.id)}" ${(p.currency||db.settings.currency)!==quoteDraft.currency?'disabled':''}><strong>${esc(p.name)}</strong><small>${esc(p.sku||'No SKU')} · ${esc(p.currency||db.settings.currency)} · ${money(p.price,p.currency)}</small><span>${(p.currency||db.settings.currency)===quoteDraft.currency?'+':'Different currency'}</span></button>`).join('')||'<p class="quiet-state">No matching catalog items. Add a manual line to continue.</p>';}
  document.addEventListener('input',e=>{const el=e.target;if(modal.open&&modal.contains(el)&&el.closest('form'))modal.dataset.dirty='true';if(el.id==='command-query')renderCommands(el.value);if(el.id==='catalog-query')renderCatalogResults(el.value);if(!document.querySelector('.quote-builder')||!quoteDraft)return;const map={'q-title':'title','q-customer':'customerId','q-currency':'currency','q-date':'created','q-expiry':'expiry','q-payment':'payment','q-delivery':'delivery','q-discount':'discount','q-notes':'notes'};if(map[el.id]){quoteDraft[map[el.id]]=el.id==='q-discount'?Number(el.value):el.value;if(el.id==='q-currency')quoteDraft.items.filter(i=>!i.catalogItemId).forEach(i=>i.currency=el.value);}if(el.matches('[data-item]')){const key=el.dataset.key;quoteDraft.items[Number(el.dataset.item)][key]=['qty','cost','price','tax'].includes(key)?Number(el.value):el.value;}if(map[el.id]||el.matches('[data-item]')){quoteDirty=true;const state=document.getElementById('save-state');if(state)state.textContent='Unsaved changes';updateCommercialPreview();}});
