  const reportClientError=(message,path=location.pathname)=>fetch('/api/client-error',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:String(message).slice(0,500),path})}).catch(()=>{});
  window.addEventListener('error',event=>reportClientError(event.message));
