  async function loadAccount(){const me=await api('/api/auth/me');const data=await api('/api/bootstrap');account=me;history.replaceState({},'', '/workspace');db={settings:data.settings,customers:data.customers,products:data.products,rfqs:data.rfqs,quotes:data.quotes,followups:data.followups,events:data.events};localStorage.removeItem(AUTH);page='Dashboard';render();}
  async function acceptInvitation(){if(!INVITE_TOKEN)return;const result=await api('/api/team/accept',{method:'POST',body:JSON.stringify({token:INVITE_TOKEN})});history.replaceState({},'', '/');toast(`Joined ${result.organization.name} as ${result.role}.`);await loadAccount();}
  async function switchOrganization(organizationId){const select=document.getElementById('active-org');if(select)select.disabled=true;try{await api('/api/auth/switch-organization',{method:'POST',body:JSON.stringify({organizationId})});localStorage.removeItem(AUTH);await loadAccount();toast(`Switched to ${account.organization.name}.`);}catch(error){toast(error.message,'error');await loadAccount().catch(()=>{});}finally{const active=document.getElementById('active-org');if(active)active.disabled=false;}}
  const app=document.getElementById('app'), modal=document.getElementById('modal');
  const money=(amount,currency=db.settings.currency)=>new Intl.NumberFormat('en-AE',{style:'currency',currency:currency||'AED',currencyDisplay:'code',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(amount)||0);
  const niceDate=(value)=>value?new Date(`${value}T12:00:00`).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
  const getCustomer=(id)=>db.customers.find(x=>x.id===id);
  const getQuote=(id)=>db.quotes.find(x=>x.id===id);
  const getRFQ=(id)=>db.rfqs.find(x=>x.id===id);
  const quoteMath=(q)=>{const raw=(q.items||[]).reduce((a,i)=>a+Math.max(0,+i.qty||0)*Math.max(0,+i.price||0),0);const discount=Math.min(raw,Math.max(0,+q.discount||0));const subtotal=raw-discount;const tax=(q.items||[]).reduce((a,i)=>a+(Math.max(0,+i.qty||0)*Math.max(0,+i.price||0)-discount*(raw?Math.max(0,+i.qty||0)*Math.max(0,+i.price||0)/raw:0))*Math.max(0,+i.tax||0)/100,0);const cost=(q.items||[]).reduce((a,i)=>a+Math.max(0,+i.qty||0)*Math.max(0,+i.cost||0),0);const profit=subtotal-cost;return{subtotal,discount,tax,total:subtotal+tax,cost,profit,margin:subtotal?profit/subtotal*100:0};};
  const statusTone=(s)=>({Approved:'green','Needs approval':'amber',Sending:'blue',Declined:'red',Overdue:'red','Due today':'amber',Accepted:'green',Won:'green',Sent:'blue',Viewed:'blue',Pricing:'amber',Reviewing:'amber',New:'gray',Draft:'gray',Rejected:'red',Lost:'red',Expired:'red',Quoted:'blue',Completed:'green',Pending:'amber',Snoozed:'gray'}[s]||'gray');
