  function renderLanding(){const [title,desc]=landingPages[location.pathname]||['From RFQ to professional quote in minutes','QuoteFlow helps suppliers and service businesses capture requests, price jobs, create polished proposals and follow up — all from one workspace.'];document.title=`${title} — QuoteFlow`;app.innerHTML=`<div style="background:#fff;min-height:100vh"><header style="height:68px;max-width:1160px;margin:auto;padding:0 24px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)">${logo()}<nav style="display:flex;gap:21px;align-items:center;font-size:13px;color:#596577"><a href="/features">Features</a><a href="/pricing">Pricing</a><a href="/rfq-software">For suppliers</a><button class="btn" data-action="enter-demo">Open demo</button></nav></header><section style="max-width:1160px;margin:0 auto;padding:92px 24px 70px;display:grid;grid-template-columns:1.05fr .95fr;gap:46px;align-items:center"><div><div class="eyebrow">RFQ & QUOTATION WORKSPACE FOR B2B TEAMS</div><h1 style="font:800 clamp(34px,5vw,55px)/1.09 Manrope;letter-spacing:-2px;max-width:610px;margin:12px 0 17px">${esc(title)}</h1><p style="font-size:15px;line-height:1.75;color:#667386;max-width:540px">${esc(desc)}</p><div style="display:flex;gap:9px;margin-top:25px"><button class="btn primary" data-action="enter-demo">Try the demo ${icon('arrow')}</button><a href="/features" class="btn">See how it works</a></div><div style="margin-top:16px;font-size:13px;color:#8993a1">No credit card · No signup · Clearly labeled sample data</div></div><div style="background:#f5f7fb;border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:var(--shadow)"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><strong style="font:700 12px Manrope">A clearer quoting workflow</strong><span class="badge blue">DEMO VIEW</span></div><div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;align-items:center">${[['RFQ','Request'],['box','Price'],['file','Quote'],['arrow','Share'],['check','Win']].map(([ic,label],i)=>`<div style="background:#fff;border:1px solid var(--line);border-radius:9px;padding:13px 6px;text-align:center"><div style="color:${i===4?'#178361':'#2d5bdb'}">${ic==='RFQ'?'01':icon(ic,16)}</div><div style="font-size:12px;font-weight:600;margin-top:7px">${label}</div></div>`).join('')}</div><div class="panel" style="margin-top:14px;padding:14px"><div style="display:flex;justify-content:space-between;font-size:13px"><b>Q-2026-008 · Guest room workspace</b>${badge('Sent')}</div><div style="color:#8993a1;font-size:12px;margin-top:7px">Horizon Hospitality · Valid until ${niceDate(dateOffset(29))}</div><div style="font:700 18px Manrope;margin-top:14px">${money(quoteMath(getQuote('q1')).total)}</div></div></div></section><section style="background:#f7f8fa;padding:54px 24px"><div style="max-width:1100px;margin:auto;text-align:center"><div class="eyebrow">LESS ADMIN BETWEEN REQUEST AND REVENUE</div><h2 style="font:700 25px Manrope;margin:0">The core work, in one calm workspace.</h2><div class="section-row" style="margin-top:23px;text-align:left"><div class="panel" style="padding:21px"><span class="metric-icon">${icon('inbox')}</span><h3 style="font:700 14px Manrope">Start with the request</h3><p style="font-size:13px;color:#687486;line-height:1.7">Capture an RFQ, add requested items and review extracted suggestions before they become quote lines.</p></div><div class="panel" style="padding:21px"><span class="metric-icon">${icon('chart')}</span><h3 style="font:700 14px Manrope">Price with context</h3><p style="font-size:13px;color:#687486;line-height:1.7">See estimated cost, gross profit and margin while you prepare the offer.</p></div></div><div class="section-row" style="text-align:left"><div class="panel" style="padding:21px"><span class="metric-icon">${icon('file')}</span><h3 style="font:700 14px Manrope">Send a stronger quote</h3><p style="font-size:13px;color:#687486;line-height:1.7">Preview a clean customer-facing document and download a revision-bound server PDF.</p></div><div class="panel" style="padding:21px"><span class="metric-icon">${icon('calendar')}</span><h3 style="font:700 14px Manrope">Keep the follow-up visible</h3><p style="font-size:13px;color:#687486;line-height:1.7">Track customer responses and due tasks instead of losing the next step in a mailbox.</p></div></div></div></section><section style="padding:52px 24px;text-align:center"><div class="eyebrow">A FOCUSED START</div><h2 style="font:700 23px Manrope">Try the sample workspace</h2><p style="font-size:13px;color:#687486">Explore demo dashboard, RFQs, quotes, customer portal and follow-ups. All records are fictional.</p><button class="btn primary" data-action="enter-demo">Open QuoteFlow demo ${icon('arrow')}</button><p style="font-size:12px;color:#929baa;margin-top:19px">Plans and prices remain hypotheses until validated with real customers.</p></section><footer style="border-top:1px solid var(--line);padding:20px 24px;display:flex;justify-content:center;gap:18px;font-size:12px;color:#818c9b"><span>© QuoteFlow demo</span><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/security">Security</a><a href="/contact">Contact</a></footer></div>`;}
  function shell(content){const orgName=account?.organization?.name||db.settings.company,person=account?.user?.email||'Demo owner';app.innerHTML=`<a class="skip-link" href="#workspace-content">Skip to content</a><div class="app-shell"><aside class="sidebar" id="sidebar" aria-label="Workspace navigation">${logo()}<button class="workspace-control" data-action="workspace-menu" aria-haspopup="dialog"><span class="org-avatar">${esc(orgName.slice(0,2).toUpperCase())}</span><span class="org-info"><strong>${esc(orgName)}</strong><small>${roleLabel(account?.role||'OWNER')}${account?'':' · Fictional demo'}</small></span><span aria-hidden="true">⌄</span></button><div class="nav-label">COMMERCIAL WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navItems.map(([n,i])=>`<button class="${page===n?'active':''}" ${page===n?'aria-current="page"':''} data-page="${n}">${icon(i)}${esc(pageLabel(n))}${n==='Quotations'&&db.quotes.some(q=>q.status==='Internal Review')?`<span class="nav-count">${db.quotes.filter(q=>q.status==='Internal Review').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><nav class="nav"><button data-page="Settings" class="${page==='Settings'?'active':''}">${icon('settings')}Settings</button>${account?'<button data-action="signout">Sign out</button>':'<button data-action="demo-reset">Reset fictional demo</button><a class="btn" href="/login">Sign in to your account</a>'}</nav>${!account?'<div class="demo-note"><b>Demo workspace</b>Fictional records. Nothing is emailed.</div>':''}<div class="user-row"><span class="user-avatar">${esc(person.slice(0,2).toUpperCase())}</span><span class="user-meta"><strong>${esc(person)}</strong><small>${account?'Organization account':'Explore the full workflow'}</small></span></div></div></aside><section class="main"><header class="topbar"><div class="topbar-start"><button class="icon-btn mobile-menu" id="menu-toggle" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="crumb">Workspace <span aria-hidden="true"> / </span><b>${esc(pageLabel(page))}</b></div></div><div class="top-actions"><button class="search-trigger" data-action="command-search">${icon('search')}<span>Search or jump to…</span><kbd>Ctrl K</kbd></button>${canWrite()?'<button class="btn primary" data-action="quick-create">+ New</button>':''}</div></header><div class="content" id="workspace-content" tabindex="-1">${content}</div></section></div>`;enhanceControls();}
  const head=(kicker,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
