  function render(){if(location.pathname.startsWith('/q/'))return renderPortal(decodeURIComponent(location.pathname.split('/').pop()));if(location.pathname==='/login'&&!account)return renderLogin();const views={'Dashboard':dashboard,'RFQs':rfqsPage,'Quotations':quotesPage,'Customers':customersPage,'Products & services':productsPage,'Analytics':analyticsPage,'Follow-ups':followupsPage,'Settings':settingsPage};shell((views[page]||dashboard)());if(page==='Settings'&&account)loadBillingPanel();window.scrollTo(0,0);}
