  function dashboard(){const currency=dashboardCurrency||db.settings.currency||'AED',qs=db.quotes.filter(q=>q.currency===currency),open=qs.filter(q=>['Draft','Internal Review','Sent','Viewed'].includes(q.status)&&!expiredQuote(q)),won=qs.filter(q=>q.status==='Accepted'),due=db.followups.filter(f=>f.status==='Pending'&&f.due<=dateOffset(0));const attention=[...db.quotes.filter(q=>q.status==='Internal Review').map(q=>({id:q.id,title:q.title,detail:'Needs manager approval',kind:'quote',tone:'amber'})),...db.quotes.filter(q=>['Sent','Viewed'].includes(q.status)&&daysUntil(q.expiry)>=0&&daysUntil(q.expiry)<=3).map(q=>({id:q.id,title:q.title,detail:deadlineText(q.expiry,'Expires'),kind:'quote',tone:'amber'})),...due.map(f=>({id:f.quoteId,title:f.title,detail:deadlineText(f.due,'Due'),kind:'quote',tone:'red'})),...db.rfqs.filter(r=>!['Quoted','Won','Lost','Cancelled'].includes(r.status)&&daysUntil(r.deadline)<=3).map(r=>({id:r.id,title:r.title,detail:deadlineText(r.deadline,'Due'),kind:'rfq',tone:'amber'}))];return `${head('COMMERCIAL OVERVIEW','Your next move, made clear.','Requests, quotations and customer decisions in one place.',currencyControl(currency))}<div class="metric-grid commercial-metrics">${metric('Open quoted value',money(open.reduce((s,q)=>s+quoteMath(q).total,0),currency),`${open.length} active quotes · ${currency}`)}${metric('Awaiting customer',qs.filter(q=>['Sent','Viewed'].includes(q.status)&&!expiredQuote(q)).length,'Sent and viewed quotes')}${metric('Accepted value',money(won.reduce((s,q)=>s+quoteMath(q).total,0),currency),`${won.length} accepted quotes · ${currency}`)}${metric('Open RFQs',db.rfqs.filter(r=>!['Quoted','Won','Lost','Cancelled'].includes(r.status)).length,'Requests ready for the next step')}</div>${!account?'<p class="context-note">Demo data is fictional. Try an RFQ, build a quote, then open the customer view.</p>':''}${!db.customers.length?`<section class="onboarding"><h2>Your first quotation starts here.</h2><p>Set your company details, add a customer and build an offer. You can add catalog items as you go.</p><div class="actions"><button class="btn" data-page="Settings">1. Company details</button><button class="btn primary" data-action="new-customer">2. Add customer</button><button class="btn" data-action="new-quote">3. Create quote</button></div></section>`:''}<div class="dashboard-columns"><section class="panel attention-panel"><div class="panel-head"><h2>Needs your attention</h2><span class="count-label">${attention.length} ${attention.length===1?'item':'items'}</span></div>${attention.length?attention.slice(0,8).map(a=>`<button class="attention-row" data-open-${a.kind}="${esc(a.id)}"><span class="attention-marker ${a.tone}"></span><span><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></span><span aria-hidden="true">↗</span></button>`).join(''):'<div class="quiet-state"><h3>You’re up to date.</h3><p>No approvals, deadlines or overdue follow-ups need your attention.</p></div>'}</section><section class="panel"><div class="panel-head"><h2>Recent activity</h2><button class="text-link" data-page="Quotations">View quotes →</button></div>${activityTimeline(db.events.slice(0,6))}</section></div><section class="section-block"><div class="section-heading"><div><h2>Quotations in motion</h2><p>Recent offers and their next step.</p></div><button class="btn" data-page="Quotations">All quotes →</button></div>${quoteTable([...db.quotes].sort((a,b)=>String(b.created).localeCompare(String(a.created))).slice(0,5))}</section>`;}
  function empty(title,desc,action,label){return `<div class="empty-state"><div class="empty-icon">${icon('file')}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p><button class="btn primary" data-action="${action}">${icon('plus')}${esc(label)}</button></div>`;}
  function rfqsPage(){const list=db.rfqs.filter(r=>currentFilter==='All'||r.status===currentFilter);return `${head('SALES WORKSPACE','RFQs','Capture customer requests and keep the next step clear.',actionBtn('new-rfq',`${icon('plus')} New RFQ`,'primary'))}<section class="panel"><div class="table-controls"><input class="search" id="table-search" placeholder="Search RFQs or customers…"/><div class="filter-row"><select class="select" id="status-filter"><option>All</option>${['New','Reviewing','Pricing','Quoted','Won','Lost','Expired','Cancelled'].map(s=>`<option ${currentFilter===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn" data-action="import-rfq">${icon('plus')} Paste RFQ</button></div></div><div id="rfq-table">${rfqTable(list)}</div></section>`;}
  function rfqTable(list){return list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Customer</th><th>Items</th><th>Deadline</th><th>Status</th><th>Next step</th></tr></thead><tbody>${list.map(r=>`<tr><td><button class="row-link" data-open-rfq="${esc(r.id)}">${esc(r.title)}<span>${esc(r.number)} · Received ${niceDate(r.received)}</span></button></td><td>${esc(customerName(r.customerId))}</td><td>${r.items?.length||0}</td><td class="${daysUntil(r.deadline)<0?'text-warning':''}">${deadlineText(r.deadline,'Due')}<small class="cell-meta">${niceDate(r.deadline)}</small></td><td>${badge(r.status)}</td><td><button class="btn" data-open-rfq="${esc(r.id)}">${['Quoted','Won','Lost','Cancelled'].includes(r.status)?'View request':'Review request'} →</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${list.length} requests</span><span>${account?'Organization records':'Fictional demo records'}</span></div>`:empty('No requests here','Capture the original customer request and review its requirements.','new-rfq','Create RFQ');}
  function quotesPage(){const list=db.quotes.filter(q=>currentFilter==='All'||(currentFilter==='Expired'?expiredQuote(q):!expiredQuote(q)&&q.status===currentFilter));return `${head('SALES WORKSPACE','Quotations','Build clear offers, track responses and follow up at the right time.',actionBtn('new-quote',`${icon('plus')} New quote`,'primary'))}<section class="panel"><div class="table-controls"><input class="search" id="table-search" placeholder="Search quotes or customers…"/><div class="filter-row"><select class="select" id="status-filter"><option>All</option>${['Draft','Internal Review','Sent','Viewed','Accepted','Rejected','Expired'].map(s=>`<option value="${s}" ${currentFilter===s?'selected':''}>${statusText(s)}</option>`).join('')}</select><button class="btn" data-action="export-quotes">${icon('download')} Export CSV</button></div></div><div id="quote-table">${quoteTable(list)}</div></section>`;}
  function quoteTable(list){return list.length?`<div class="table-wrap"><table class="data-table quote-list"><thead><tr><th>Quote / customer</th><th class="numeric">Value</th><th class="numeric">Margin</th><th>Status</th><th>Version</th><th>Valid until</th><th>Next step</th></tr></thead><tbody>${list.map(q=>{const m=quoteMath(q),status=expiredQuote(q)?'Expired':q.status;return `<tr><td><button class="row-link" data-open-quote="${esc(q.id)}">${esc(q.title)}<span>${esc(q.number)} · ${esc(customerName(q.customerId))}</span></button></td><td class="numeric">${money(m.total,q.currency)}</td><td class="numeric ${m.margin<Number(db.settings.margin??20)?'text-warning':''}">${m.margin.toFixed(1)}%</td><td>${badge(status)}</td><td>v${Number(q.version)||1}</td><td><span>${niceDate(q.expiry)}</span><small class="cell-meta">${deadlineText(q.expiry,'Expires')}</small></td><td><button class="btn" data-preview-quote="${esc(q.id)}">${q.status==='Internal Review'?'Review':q.status==='Draft'?'Continue':'View quote'} →</button></td></tr>`}).join('')}</tbody></table></div><div class="table-footer"><span>${list.length} quotations</span><span>Each value retains its quote currency</span></div>`:empty('No quotations yet','Start from an RFQ or create an offer from scratch.','new-quote','Create quotation');}
  function customersPage(){return `${head('RELATIONSHIPS','Customers','Keep contacts and commercial activity together.',actionBtn('new-customer',`${icon('plus')} Add customer`,'primary'))}<section class="panel"><div class="table-controls"><input class="search" id="table-search" placeholder="Search customers…"/><button class="btn" data-action="export-customers">${icon('download')} Export CSV</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>COMPANY</th><th>CONTACT</th><th>EMAIL</th><th>INDUSTRY</th><th>QUOTES</th><th>WON VALUE</th><th></th></tr></thead><tbody id="customer-table">${customerRows(db.customers)}</tbody></table></div><div class="table-footer"><span>${db.customers.length} customers</span><span>Demo customer details use reserved .example domains</span></div></section>`;}
  function customerRows(list){return list.length?list.map(c=>{const qs=db.quotes.filter(q=>q.customerId===c.id);const won=currencyTotals(qs.filter(q=>['Accepted','Won'].includes(q.status)));return `<tr data-open-customer="${c.id}"><td class="primary-cell">${esc(c.name)}</td><td>${esc(c.contact||'—')}</td><td>${esc(c.email||'—')}</td><td>${esc(c.industry||'—')}</td><td>${qs.length}</td><td>${won}</td><td><button class="btn" data-customer-edit="${c.id}">View</button></td></tr>`}).join(''):`<tr><td colspan="7">${empty('No customers yet','Add a customer before preparing your first quote.','new-customer','Add customer')}</td></tr>`;}
  function productsPage(){return `${head('PRICING LIBRARY','Catalog','Reusable items with clear commercial guardrails.',canManage()?actionBtn('new-product','+ Add catalog item','primary'):'')}<section class="panel"><div class="table-controls"><input aria-label="Search catalog" class="search" id="table-search" placeholder="Search name, SKU or category…"/>${!account?'<button class="btn" data-action="import-csv">Import demo CSV</button>':''}<button class="btn" data-action="export-products">Export CSV</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Item / SKU</th><th>Category</th><th class="numeric">Cost</th><th class="numeric">Sell</th><th class="numeric">Minimum</th><th class="numeric">Margin</th><th>Tax</th><th>Status</th></tr></thead><tbody id="product-table">${productRows(db.products)}</tbody></table></div></section>`;}
  function productRows(list){return list.length?list.map(p=>`<tr><td><button class="row-link" data-product-edit="${esc(p.id)}">${esc(p.name)}<span>${esc(p.sku||'No SKU')} · ${esc(p.unit||'each')}</span></button></td><td>${esc(p.category||'—')}</td><td class="numeric">${money(p.cost,p.currency)}</td><td class="numeric">${money(p.price,p.currency)}</td><td class="numeric">${p.minimumPrice==null?'—':money(p.minimumPrice,p.currency)}</td><td class="numeric">${p.price?((p.price-p.cost)/p.price*100).toFixed(1):'0.0'}%</td><td>${Number(p.tax??db.settings.tax??0)}%</td><td>${badge(p.active===false?'Inactive':'Active')}</td></tr>`).join(''):`<tr><td colspan="8">${empty('Build your pricing library','Add your first catalog item to quote faster.','new-product','Add catalog item')}</td></tr>`;}
  function analyticsPage(){const currency=dashboardCurrency||db.settings.currency||'AED',qs=db.quotes.filter(q=>q.currency===currency),won=qs.filter(q=>q.status==='Accepted'),decided=qs.filter(q=>['Accepted','Rejected'].includes(q.status)),sum=list=>list.reduce((s,q)=>s+quoteMath(q).total,0);return `${head('COMMERCIAL PERFORMANCE','From quotation to outcome.','All saved records. Values are grouped by currency; no exchange conversion.',currencyControl(currency))}<div class="metric-grid commercial-metrics">${metric('Quoted value',money(sum(qs),currency),`${qs.length} quotes · all statuses`)}${metric('Accepted value',money(sum(won),currency),`${won.length} accepted`)}${metric('Win rate',decided.length?`${Math.round(won.length/decided.length*100)}%`:'—',`${decided.length} customer decisions`)}${metric('Average margin',qs.length?`${(qs.reduce((s,q)=>s+quoteMath(q).margin,0)/qs.length).toFixed(1)}%`:'—','Unweighted average of quote margins')}</div><section class="panel"><div class="panel-head"><h2>Where quotations stand</h2><span>${esc(currency)}</span></div><div class="outcomes">${['Draft','Internal Review','Sending','Sent','Viewed','Accepted','Rejected'].map(status=>{const n=qs.filter(q=>q.status===status).length;return `<div class="outcome-row">${badge(status)}<div class="outcome-track"><span style="width:${qs.length?n/qs.length*100:0}%"></span></div><strong>${n}</strong><span class="numeric">${money(sum(qs.filter(q=>q.status===status)),currency)}</span></div>`}).join('')}</div></section><p class="context-note">Win rate includes accepted and declined quotes only. Historical versions may be separate records; these are record totals, not a deduplicated sales forecast.</p>`;}
  function followupsPage(){const groups=[['Overdue',f=>f.status==='Pending'&&f.due<dateOffset(0)],['Due today',f=>f.status==='Pending'&&f.due===dateOffset(0)],['Upcoming',f=>!['Completed'].includes(f.status)&&f.due>dateOffset(0)],['Completed',f=>f.status==='Completed']];return `${head('CUSTOMER FOLLOW-UP','Keep the conversation moving.','A clear next action for every quotation.',actionBtn('new-followup','+ Add follow-up','primary'))}${groups.map(([title,filter])=>{const rows=db.followups.filter(filter).sort((a,b)=>a.due.localeCompare(b.due));return `<section class="section-block"><div class="section-heading"><h2>${title} <span class="count-label">${rows.length}</span></h2></div>${rows.length?`<div class="panel">${rows.map(f=>`<div class="task-row"><div><strong>${esc(f.title)}</strong><p><button class="text-link" data-open-quote="${esc(f.quoteId)}">${esc(getQuote(f.quoteId)?.number||'Quote')}</button> · ${esc(customerName(getQuote(f.quoteId)?.customerId))}</p>${f.note?`<p>${esc(f.note)}</p>`:''}</div><span>${niceDate(f.due)}</span>${f.status!=='Completed'?`<button class="btn" data-complete-follow="${esc(f.id)}">${icon('check')} Complete</button>`:badge('Completed')}</div>`).join('')}</div>`:'<p class="context-note">No '+title.toLowerCase()+' follow-ups.</p>'}</section>`}).join('')}`;}
  function settingsPage(){return `${head('WORKSPACE','Company settings','Set sensible defaults for the quotes your team prepares.',`<button class="btn primary" data-action="save-settings">${icon('check')} Save settings</button>`)}<div class="settings-grid">${verificationCard()}${account?`<section class="panel setting-card"><h3>Account security</h3><div class="customer-stat"><span>Email status</span><b>${account.user.verified?'Verified':'Verification required'}</b></div><p class="context-note">Password changes revoke your other sessions. Organization Owners can manage roles and transfer ownership from Team security.</p><div class="actions"><button class="btn" data-action="change-password">Change password</button><button class="btn" data-action="logout-other-sessions">Log out other sessions</button>${['OWNER','ADMIN'].includes(account.role)?'<button class="btn" data-action="manage-team-security">Team security</button>':''}</div></section>`:''}<section class="panel setting-card"><h3>Company profile</h3><div class="field"><label for="set-company">Company name</label><input id="set-company" value="${esc(db.settings.company)}"/></div><div class="field"><label for="set-email">Business email</label><input id="set-email" type="email" value="${esc(db.settings.email)}"/></div><div class="field"><label for="set-phone">Phone</label><input id="set-phone" value="${esc(db.settings.phone)}"/></div><div class="field"><label for="set-address">Address</label><textarea id="set-address">${esc(db.settings.address)}</textarea></div></section><section class="panel setting-card"><h3>Commercial defaults</h3><div class="field"><label for="set-currency">Default currency</label><select id="set-currency">${['AED','USD','EUR','GBP','SAR'].map(c=>`<option ${db.settings.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="set-tax">Default tax rate (%)</label><input id="set-tax" type="number" min="0" max="100" value="${+db.settings.tax||0}"/></div><div class="field"><label for="set-margin">Minimum gross margin (%)</label><input id="set-margin" type="number" min="0" max="100" value="${+db.settings.margin||0}"/></div><div class="field"><label for="set-validity">Quote validity (days)</label><input id="set-validity" type="number" min="1" max="365" value="${+db.settings.validity||30}"/></div></section><section class="panel setting-card"><h3>Terms shown on new quotes</h3><div class="field"><label for="set-payment">Payment terms</label><input id="set-payment" value="${esc(db.settings.payment)}"/></div><div class="field"><label for="set-delivery">Delivery terms</label><textarea id="set-delivery">${esc(db.settings.delivery)}</textarea></div><div class="field"><label for="set-template">Quote template</label><select id="set-template">${['Standard'].map(t=>`<option ${db.settings.template===t?'selected':''}>${t}</option>`).join('')}</select></div></section><section class="panel setting-card" id="billing-panel" aria-live="polite"><h3>Plan & billing</h3><p class="context-note">Loading server-authoritative plan and usage…</p></section><section class="panel setting-card"><h3>Connected services</h3><p style="font-size:13px;color:#697587;line-height:1.7">AI, email, billing and storage are configured by the deployment owner. Provider credentials never enter the browser.</p><div class="customer-stat"><span>AI provider</span><b>Environment managed</b></div><div class="customer-stat"><span>Email sending</span><b>Environment managed</b></div><div class="customer-stat"><span>Object storage</span><b>Environment managed</b></div></section><section class="panel setting-card"><h3>Data control</h3><p class="context-note">Organization Owners can export all commercial records or start a seven-day deletion cooling-off period.</p><div class="actions"><button class="btn" data-action="export-account-data">Export organization data</button>${account?.role==='OWNER'?'<button class="btn danger" data-action="request-account-deletion">Request deletion</button>':''}</div></section></div>`;}
  async function loadBillingPanel(){const panel=document.getElementById('billing-panel');if(!panel)return;try{const result=await api('/api/billing'),e=result.entitlements,s=result.subscription;panel.innerHTML=`<h3>Plan & billing</h3><div class="customer-stat"><span>Current plan</span><b>${esc(e.plan)}</b></div><div class="customer-stat"><span>Status</span><b>${esc(s?.status||'ACTIVE')}</b></div>${s?.currentPeriodEnd?`<div class="customer-stat"><span>${s.cancelAtPeriodEnd?'Access through':'Renews'}</span><b>${niceDate(s.currentPeriodEnd)}</b></div>`:''}<div class="usage-list"><div><span>Team</span><b>${e.usage.teamMembers} / ${e.limits.teamMembers}</b></div><div><span>Quotes this month</span><b>${e.usage.quotesThisMonth} / ${e.limits.quotesPerMonth}</b></div><div><span>AI requests</span><b>${e.usage.aiRequestsThisMonth} / ${e.limits.aiRequestsPerMonth}</b></div><div><span>Storage</span><b>${(e.usage.storageBytes/1048576).toFixed(1)} / ${(e.limits.storageBytes/1048576).toFixed(0)} MB</b></div></div><div class="actions">${result.billingEnabled&&['OWNER','ADMIN'].includes(account.role)?`${e.plan==='FREE'?'<button class="btn primary" data-action="start-checkout" data-plan="PRO">Choose Pro</button><button class="btn" data-action="start-checkout" data-plan="BUSINESS">Choose Business</button>':'<button class="btn primary" data-action="open-billing-portal">Manage billing</button>'}`:'<span class="context-note">Billing checkout is not enabled for this deployment.</span>'}</div><p class="context-note">Past-due plans keep paid entitlements for a seven-day grace period. Customer data is never deleted automatically for payment failure.</p>${result.deletionRequest?`<div class="commercial-notice warning"><b>Deletion requested — operator processing from ${niceDate(result.deletionRequest.scheduledFor)}</b><br>The Owner can cancel during the cooling-off period.<div class="actions" style="margin-top:10px"><button class="btn" data-action="cancel-account-deletion">Cancel deletion request</button></div></div>`:''}`;}catch(error){panel.innerHTML=`<h3>Plan & billing</h3><p class="text-warning">${esc(error.message)}</p>`;}}
  async function openTeamSecurity(){try{const result=await api('/api/team');const eligible=result.members.filter(member=>member.userId!==account.user.id&&member.role!=='OWNER');showModal('Team security',`<div style="display:grid;gap:8px">${result.members.map(member=>`<div class="customer-stat"><span>${esc(member.email)}</span><b>${esc(roleLabel(member.role))}</b></div>`).join('')}</div>${account.role==='OWNER'&&eligible.length?`<hr/><p class="context-note">Ownership transfer takes effect immediately. You become an Admin.</p><div class="field"><label for="ownership-target">New Owner</label><select id="ownership-target">${eligible.map(member=>`<option value="${esc(member.userId)}">${esc(member.email)} · ${esc(roleLabel(member.role))}</option>`).join('')}</select></div><div class="field"><label for="ownership-password">Current password</label><input id="ownership-password" type="password" autocomplete="current-password"/></div>`:''}`,`<button class="btn" data-action="close-modal">Close</button>${account.role==='OWNER'&&eligible.length?'<button class="btn danger" data-action="confirm-ownership-transfer">Transfer ownership</button>':''}`);}catch(error){toast(error.message,'error');}}
  async function changePasswordFromDialog(){const currentPassword=document.getElementById('security-current-password').value,newPassword=document.getElementById('security-new-password').value;if(newPassword.length<12){toast('New password must contain at least 12 characters.','error');return;}try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword,newPassword})});modal.close();toast('Password changed. Other sessions were revoked.');}catch(error){toast(error.message,'error');}}
  function showModal(title,body,foot=''){modal.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}<div class="form-error" id="dialog-error" role="alert" hidden></div></div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;modal.setAttribute('aria-labelledby','dialog-title');if(!modal.open)modal.showModal();enhanceControls();}
  function field(label,id,value='',type='text',opts={}){return `<div class="field ${opts.full?'full':''}"><label for="${id}">${esc(label)}</label>${type==='textarea'?`<textarea id="${id}" ${opts.maxlength?`maxlength="${opts.maxlength}"`:''} ${opts.required?'required':''}>${esc(value)}</textarea>`:type==='select'?`<select id="${id}" ${opts.required?'required':''}>${opts.options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input id="${id}" type="${type}" value="${esc(value)}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.step?`step="${opts.step}"`:''}/>`}</div>`;}
  function addCustomerModal(){showModal('Add customer',`<form id="customer-form" class="form-grid">${field('Company name','c-name','','text',{required:true,full:true})}${field('Contact name','c-contact')}${field('Email','c-email','', 'email')}${field('Phone','c-phone')}${field('Industry','c-industry')}${field('Address','c-address','','text',{full:true})}${field('Notes','c-notes','','textarea',{full:true})}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-customer">Save customer</button>`);}
  function addProductModal(product=null){showModal(product?'Edit catalog item':'Add product or service',`<form id="product-form" class="form-grid">${field('Item name','p-name',product?.name||'','text',{required:true,full:true})}${field('SKU / item code','p-sku',product?.sku||'')}${field('Category','p-category',product?.category||'Products')}${field('Unit','p-unit',product?.unit||'each')}${field('Cost price','p-cost',product?.cost??0,'number',{min:0,step:'0.0001'})}${field('Selling price','p-price',product?.price??0,'number',{min:0,step:'0.0001'})}${field('Minimum selling price','p-minimum',product?.minimumPrice??'','number',{min:0,step:'0.0001'})}${field('Tax rate (%)','p-tax',product?.tax??db.settings.tax??0,'number',{min:0,max:100,step:'0.0001'})}${field('Currency','p-currency',product?.currency||db.settings.currency,'select',{options:['AED','USD','EUR','GBP','SAR'].map(x=>[x,x])})}${field('Active','p-active',String(product?.active!==false),'select',{options:[['true','Active'],['false','Inactive']]})}${field('Description','p-description',product?.description||'','textarea',{full:true})}${account?'<button type="button" class="btn" data-action="ai-product-description">Improve description with AI</button>':''}</form><input type="hidden" id="p-edit-id" value="${product?.id||''}"/>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-product">Save item</button>`);}
  function addRfqModal(r=null){showModal(r?'Edit RFQ':'Create RFQ',`<form id="rfq-form" class="form-grid">${field('Request title','r-title',r?.title||'','text',{required:true,full:true})}${field('Customer','r-customer',r?.customerId||db.customers[0]?.id||'','select',{required:true,options:db.customers.map(c=>[c.id,c.name])})}${field('Received','r-received',r?.received||dateOffset(0),'date',{required:true})}${field('Deadline','r-deadline',r?.deadline||dateOffset(7),'date')}${field('Priority','r-priority',r?.priority||'Normal','select',{options:[['Normal','Normal'],['High','High'],['Urgent','Urgent']]})}${field('Status','r-status',r?.status||'New','select',{options:['New','Reviewing','Pricing','Quoted','Won','Lost','Expired','Cancelled'].map(x=>[x,x])})}${field('Source','r-source',r?.source||'Email')}${field('Notes','r-notes',r?.notes||'','textarea',{full:true})}${!r&&account?'<div class="field full"><label for="r-attachment">RFQ attachment (optional)</label><input id="r-attachment" type="file" accept=".pdf,.csv,.xls,.xlsx,.doc,.docx,.png,.jpg,.jpeg,.webp"/><small class="context-note">Private upload, maximum size set by the deployment. Files are verified before use.</small></div>':''}</form><input type="hidden" id="r-edit-id" value="${r?.id||''}"/>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-rfq">Save RFQ</button>`);}
  function importRfqModal(){window.__rfqAIResult=null;showModal('Capture an RFQ',`<form id="import-form"><div class="field"><label for="import-customer">Customer</label><select id="import-customer">${db.customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label for="rfq-text">Paste the request</label><textarea id="rfq-text" placeholder="Please quote 24 ergonomic task chairs and 6 executive desks. Delivery to Dubai by 30 November." style="height:150px" required></textarea></div><div style="font-size:13px;color:#8993a1;line-height:1.6;margin-top:9px">Review every suggestion before saving. Local fallback extraction is rule-based and may miss context.</div><div id="extraction-preview" style="margin-top:12px"></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button>${account?`<button class="btn" data-action="extract-rfq-ai">${icon('spark')} Extract with AI</button>`:''}<button class="btn" data-action="parse-rfq">Use fallback extraction</button><button class="btn primary" data-action="save-imported-rfq">Create RFQ</button>`);}
  function itemFromProduct(p,qty=1){return {catalogItemId:p.id,lineType:'CATALOG',currency:p.currency||db.settings.currency,name:p.name,sku:p.sku,description:p.description,qty,unit:p.unit,cost:+p.cost||0,price:+p.price||0,minimumPrice:p.minimumPrice==null?null:+p.minimumPrice,tax:p.tax==null?(+db.settings.tax||0):(+p.tax||0)};}
  function newQuote(rfq=null){quoteDirty=false;if(!db.customers.length){toast('Add a customer first.','error');return addCustomerModal();}quoteDraft=rfq?.quoteId?{...getQuote(rfq.quoteId),items:getQuote(rfq.quoteId).items.map(i=>({...i}))}:{id:null,number:`Q-${new Date().getFullYear()}-${String(Math.max(0,...db.quotes.map(q=>Number(q.number?.split('-').pop())||0))+1).padStart(3,'0')}`,customerId:rfq?.customerId||db.customers[0].id,title:rfq?.title||'',created:dateOffset(0),expiry:dateOffset(+db.settings.validity||30),status:'Draft',currency:db.settings.currency,tax:+db.settings.tax||0,discount:0,payment:db.settings.payment,delivery:db.settings.delivery,notes:'',rfqId:rfq?.id||null,token:crypto.randomUUID(),items:rfq?.items?.length?rfq.items.map(i=>{const product=db.products.find(p=>p.id===i.catalogItemId);return product?{...i,...itemFromProduct(product,i.qty),name:i.name||product.name,description:i.description||product.description}:{...i,catalogItemId:null,cost:0,price:0,tax:+db.settings.tax||0};}):[]};page='Quotations';renderQuoteEditor();}
  function renderQuoteEditor(){const q=quoteDraft;const form=`<section class="panel form-panel"><div class="section-heading"><h2>Quotation details</h2><span class="save-state" id="save-state">${quoteDirty?'Unsaved changes':'Draft'}</span></div><div class="form-grid">${field('Quotation title','q-title',q.title,'text',{required:true,full:true})}${field('Customer','q-customer',q.customerId,'select',{options:db.customers.map(c=>[c.id,c.name])})}${field('Currency','q-currency',q.currency,'select',{options:['AED','USD','EUR','GBP','SAR'].map(x=>[x,x])})}${field('Issue date','q-date',q.created,'date')}${field('Valid until','q-expiry',q.expiry,'date')}</div><div class="line-head"><div><h2>Items & pricing</h2><p class="context-note">Catalog costs and tax are verified by the server.</p></div><div class="actions"><button class="btn primary" data-action="catalog-search">+ Add item</button><button class="btn" data-action="add-quote-item">Manual line</button></div></div><div class="line-editor"><table><thead><tr><th>Item</th><th>Qty</th><th>Unit</th><th>Cost</th><th>Sell</th><th>Tax %</th><th>Margin / total</th><th></th></tr></thead><tbody>${q.items.map((i,n)=>`<tr><td><div class="line-kind">${i.catalogItemId?'Catalog':'Manual'}</div><input class="line-name" data-item="${n}" data-key="name" value="${esc(i.name)}" aria-label="Item ${n+1} name" ${i.catalogItemId?'readonly':''}/><input data-item="${n}" data-key="description" value="${esc(i.description||'')}" aria-label="Item ${n+1} description" placeholder="Description" ${i.catalogItemId?'readonly':''}/><input data-item="${n}" data-key="sku" value="${esc(i.sku||'')}" aria-label="Item ${n+1} reference" placeholder="SKU / reference" ${i.catalogItemId?'readonly':''}/></td>${[['qty','Quantity'],['unit','Unit'],['cost','Cost'],['price','Selling price'],['tax','Tax rate']].map(([key,label])=>`<td data-label="${label}"><input data-item="${n}" data-key="${key}" type="${key==='unit'?'text':'number'}" ${key==='unit'?'':'step="0.0001" min="0"'} ${key==='tax'?'max="100"':''} value="${esc(i[key])}" aria-label="Item ${n+1} ${label}" ${i.catalogItemId&&['unit','cost','tax'].includes(key)?'readonly':''}/></td>`).join('')}<td class="numeric line-result" id="line-result-${n}">${lineResult(i,q.currency)}</td><td><button class="line-remove" data-remove-item="${n}" aria-label="Remove item ${n+1}">×</button></td></tr>`).join('')}</tbody></table>${!q.items.length?'<div class="quiet-state"><h3>Start with what you’re selling.</h3><p>Search your catalog or add a manual product or service.</p></div>':''}</div><section class="section-block"><h2>Discount & terms</h2><div class="form-grid">${field('Discount ('+q.currency+')','q-discount',q.discount,'number',{min:0,step:'0.0001'})}${field('Payment terms','q-payment',q.payment)}${field('Delivery terms','q-delivery',q.delivery,'text',{full:true})}${field('Customer notes','q-notes',q.notes,'textarea',{full:true})}</div></section><div class="form-error" id="quote-error" hidden role="alert"></div></section><aside class="summary-card panel" id="commercial-summary">${commercialSummary(q)}</aside>`;shell(`${head('QUOTATION WORKSPACE',q.id?'Refine your offer.':'Build a confident quotation.',`${q.number||'New draft'} · Version ${q.version||1}`,`<button class="btn" data-page="Quotations">← Quotes</button>`)}<div class="quote-builder">${form}</div>`);}

  function addQuoteItem(){quoteDirty=true;quoteDraft.items.push({catalogItemId:null,lineType:'MANUAL',currency:quoteDraft.currency,name:'',sku:'',description:'',qty:1,unit:'each',cost:0,price:0,minimumPrice:null,tax:+db.settings.tax||0});renderQuoteEditor();}
  function quoteDocument(q,portal=false){if(q.snapshot?.items&&q.snapshot?.totals)return publicDocument({...q.snapshot,number:q.number,title:q.title,currency:q.currency,expiry:q.expiry});const c=getCustomer(q.customerId)||{};const m=quoteMath(q);return `<div class="paper"><div class="paper-brand"><div><div class="paper-logo"><span class="brand-mark">${icon('file',17)}</span>${esc(db.settings.company)}</div><div class="paper-tag">${esc(db.settings.tagline)}</div></div><div><div class="quote-word">QUOTATION</div><div class="quote-meta">${esc(q.number)}<br>Issued ${niceDate(q.created)}<br>Valid until ${niceDate(q.expiry)}</div></div></div><div class="paper-parties"><div><div class="paper-label">Prepared for</div><strong>${esc(c.name||'Customer')}</strong><p>${esc(c.contact||'')}<br>${esc(c.email||'')}<br>${esc(c.address||'')}</p></div><div><div class="paper-label">Prepared by</div><strong>${esc(db.settings.company)}</strong><p>${esc(db.settings.address)}<br>${esc(db.settings.email)} · ${esc(db.settings.phone)}</p></div></div><h2>${esc(q.title||'Quotation')}</h2><table><thead><tr><th style="width:44%">ITEM / DESCRIPTION</th><th>QTY</th><th>UNIT PRICE</th><th>TAX</th><th class="right">AMOUNT</th></tr></thead><tbody>${q.items.map(i=>`<tr><td><strong>${esc(i.name||'Item')}</strong>${i.sku?`<div style="font-size:12px;color:#929baa;margin-top:3px">${esc(i.sku)}</div>`:''}<div style="margin-top:4px;line-height:1.5">${esc(i.description||'')}</div></td><td>${esc(i.qty)} ${esc(i.unit)}</td><td>${money(i.price,q.currency)}</td><td>${+i.tax||0}%</td><td class="right">${money(Math.max(0,+i.qty||0)*Math.max(0,+i.price||0),q.currency)}</td></tr>`).join('')}</tbody></table><div class="paper-totals"><div><span>Subtotal</span><span>${money(m.subtotal+m.discount,q.currency)}</span></div>${m.discount?`<div><span>Discount</span><span>− ${money(m.discount,q.currency)}</span></div>`:''}<div><span>Tax</span><span>${money(m.tax,q.currency)}</span></div><div><span>Total ${esc(q.currency)}</span><span>${money(m.total,q.currency)}</span></div></div><div class="paper-terms"><strong>Payment</strong> · ${esc(q.payment||'As agreed')}<br><strong>Delivery</strong> · ${esc(q.delivery||'As agreed')}${q.notes?`<br><strong>Note</strong> · ${esc(q.notes)}`:''}<br><br>Thank you for the opportunity to provide this quotation. Please contact us if you have any questions about this offer.</div><div class="paper-footer"><span>${esc(db.settings.company)} · ${esc(db.settings.email)}</span><span>${esc(q.number)} · Page 1</span></div></div>`;}
  function quotePreview(q,back='Quotations'){if(modal.open)modal.close();const canAct=['Draft','Internal Review','Sent','Viewed','Accepted','Rejected'].includes(q.status),quoteExpired=q.expiry&&new Date(`${q.expiry}T23:59:59`)<new Date(),manager=account&&['OWNER','ADMIN','SALES_MANAGER'].includes(account.role),m=quoteMath(q),needsApproval=(q.status==='Internal Review'||m.margin<(+db.settings.margin||20))&&!quoteExpired;const publicPath=account?(q.publicUrl||`/q/${encodeURIComponent(q.token||'')}`):`/q/demo/${encodeURIComponent(q.token||'')}`,events=(db.events||[]).filter(event=>event.quoteId===q.id);shell(`${head('DOCUMENT PREVIEW',q.number,`${customerName(q.customerId)} · ${quoteExpired?'Expired':q.status}`,`<button class="btn" data-page="${back}">← Back</button>${canAct&&!quoteExpired&&['Draft','Internal Review'].includes(q.status)?`<button class="btn" data-action="send-quote" data-quote="${q.id}">Send quotation</button>`:''}${canAct?`<button class="btn" data-action="duplicate-quote" data-quote="${q.id}">Duplicate quote</button>`:''}${needsApproval&&manager&&['Draft','Internal Review'].includes(q.status)?`<button class="btn primary" data-action="approve-quote" data-quote="${esc(q.id)}">Approve</button>`:''}${['Sent','Viewed','Accepted','Rejected'].includes(q.status)?`<button class="btn primary" data-action="revision-dialog" data-quote="${esc(q.id)}">Create revision</button>`:''}${q.status==='Draft'&&!quoteExpired?`<button class="btn" data-action="edit-quote" data-quote="${q.id}">Edit</button>`:''}${q.status==='Internal Review'&&!quoteExpired?`<button class="btn" data-action="edit-quote" data-quote="${q.id}">Revise</button>`:''}${['Draft','Internal Review'].includes(q.status)?'':`<button class="btn" data-action="copy-link" data-quote="${q.id}">${icon('arrow')} Copy customer link</button>`}<button class="btn primary" data-action="print-quote">${icon('download')} Print / save PDF</button>`)}${commercialOverview(q)}<details class="document-disclosure" open><summary>Customer document <span>Print or save as PDF</span></summary><div class="preview-wrap">${quoteDocument(q)}</div></details>${events.length?`<section class="panel" style="margin-top:14px;padding:16px"><h3>Quote activity</h3>${events.map(event=>`<div class="customer-stat" style="align-items:flex-start"><span>${esc(event.type.replaceAll('_',' '))} ${event.type==='CUSTOMER_QUESTION'&&event.metadata?.name?`· ${esc(event.metadata.name)} (${esc(event.metadata.email||'')})`:''}</span><small>${new Date(event.createdAt).toLocaleString()}</small>${event.type==='CUSTOMER_QUESTION'?`<p style="flex-basis:100%;margin:4px 0 0;white-space:pre-wrap">${esc(event.metadata?.message||'')}</p>`:''}</div>`).join('')}</section>`:''}${['Sent','Viewed'].includes(q.status)&&!quoteExpired&&(q.token||q.publicUrl)?`<section class="panel" style="margin-top:14px;padding:14px;display:flex;justify-content:space-between;align-items:center"><span style="font-size:13px;color:#687486">Customer portal preview</span><a class="btn subtle" href="${esc(publicPath)}" target="_blank" rel="noopener">Open customer view ↗</a>${account&&q.publicUrl?`<button class="btn danger" data-action="revoke-link" data-quote="${esc(q.id)}">Revoke link</button>`:''}${account?`<button class="btn" data-action="regenerate-link" data-quote="${esc(q.id)}">Regenerate link</button>`:''}</section>`:''}`);}
  async function renderPortal(token){const demo=location.pathname.startsWith('/q/demo/');let publicQuote=null;try{if(demo){const q=(db.quotes||[]).find(x=>x.token===token);if(!q||!['Sent','Viewed','Accepted','Rejected'].includes(q.status))throw new Error('Demo quote unavailable');const c=getCustomer(q.customerId),m=quoteMath(q);publicQuote={number:q.number,title:q.title,status:q.status,expiry:q.expiry,currency:q.currency,items:q.items.map(i=>({name:i.name,sku:i.sku,description:i.description,qty:i.qty,unit:i.unit,price:i.price,tax:i.tax})),totals:{subtotal:m.subtotal,tax:m.tax,total:m.total},customer:{name:c?.name,contact:c?.contact},company:{name:db.settings.company,address:db.settings.address,email:db.settings.email,phone:db.settings.phone},terms:{payment:q.payment,delivery:q.delivery,notes:q.notes}};}else publicQuote=(await api(`/api/public/quote/${encodeURIComponent(token)}`)).quote;}catch{app.innerHTML=`<div class="portal"><div class="portal-top">${logo()}<span style="font-size:13px;color:#8993a1">Quote link</span></div><div class="portal-main"><div class="portal-card"><h2>Quotation unavailable</h2><p>This link may have expired or is not valid.</p></div></div></div>`;return;}const q={id:null,token,number:publicQuote.number,title:publicQuote.title,status:statusText(demo&&daysUntil(publicQuote.expiry)<0&&!['Accepted','Rejected'].includes(publicQuote.status)?'Expired':publicQuote.status),expiry:publicQuote.expiry,currency:publicQuote.currency,items:publicQuote.items||[],payment:publicQuote.terms?.payment,delivery:publicQuote.terms?.delivery,notes:publicQuote.terms?.notes,customerId:'public',created:dateOffset(0)};const accepted=['Accepted','Won'].includes(q.status),company=publicQuote.company?.name||'QuoteFlow',customer=publicQuote.customer?.name||'Customer',doc=publicDocument(publicQuote);app.innerHTML=`<div class="portal"><div class="portal-top"><div class="paper-logo"><span class="brand-mark">${icon('file',17)}</span>${esc(company)}</div><span style="font-size:13px;color:#8993a1">${accepted?badge('Accepted'):'Quotation for your review'}</span></div><div class="portal-main"><div class="portal-title"><div><h1>Your quotation</h1><p>${esc(q.number)} · ${esc(customer)}</p></div>${q.status==='Declined'?badge('Rejected'):''}</div><div class="portal-card">${accepted?`<div class="portal-accepted"><div style="font-size:25px">✓</div><h2>Quote accepted</h2><p style="font-size:13px">Your acceptance has been recorded.</p></div>${doc}`:doc}${!accepted&&!['Declined','Expired'].includes(q.status)?`<div class="portal-actions"><button class="btn primary" data-public-accept="${esc(token)}" data-demo="${demo}">${icon('check')} Accept quote</button><button class="btn danger" data-public-reject="${esc(token)}" data-demo="${demo}">Decline</button><button class="btn" data-action="portal-question" data-token="${esc(token)}">Ask a question</button><button class="btn" data-action="print-quote">${icon('download')} Download PDF</button></div><p style="font-size:12px;color:#8993a1;line-height:1.6;margin-top:14px">Acceptance records a name, email and response time. It is not a certified electronic signature.</p>`:''}${q.status==='Declined'?`<div class="portal-accepted" style="background:#fdf4f4;color:#ac5155"><h2>Quote declined</h2><p style="font-size:13px">Your response has been recorded.</p></div>`:''}</div><p style="text-align:center;font-size:12px;color:#9aa2ae;margin:17px">Questions? Contact ${esc(publicQuote.company?.email||'')}</p></div></div>`;}
  function publicDocument(q){const t=q.totals;return `<div class="paper"><div class="paper-brand"><div><div class="paper-logo"><span class="brand-mark">${icon('file',17)}</span>${esc(q.company?.name||'')}</div><div class="paper-tag">${esc(q.company?.address||'')}</div></div><div><div class="quote-word">QUOTATION</div><div class="quote-meta">${esc(q.number)}<br>Valid until ${niceDate(q.expiry)}</div></div></div><div class="paper-parties"><div><div class="paper-label">Prepared for</div><strong>${esc(q.customer?.name||'Customer')}</strong><p>${esc(q.customer?.contact||'')}</p></div><div><div class="paper-label">Prepared by</div><strong>${esc(q.company?.name||'')}</strong><p>${esc(q.company?.email||'')}<br>${esc(q.company?.phone||'')}</p></div></div><h2>${esc(q.title)}</h2><table><thead><tr><th>ITEM / DESCRIPTION</th><th>QTY</th><th>UNIT PRICE</th><th>TAX</th><th class="right">AMOUNT</th></tr></thead><tbody>${q.items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><div style="margin-top:4px">${esc(i.description||'')}</div></td><td>${esc(i.qty)} ${esc(i.unit)}</td><td>${money(i.price,q.currency)}</td><td>${+i.tax||0}%</td><td class="right">${money(i.qty*i.price,q.currency)}</td></tr>`).join('')}</tbody></table><div class="paper-totals"><div><span>Subtotal</span><span>${money(t.subtotal,q.currency)}</span></div>${t.discount?`<div><span>Discount</span><span>− ${money(t.discount,q.currency)}</span></div><div><span>Net subtotal</span><span>${money(t.netSubtotal??t.subtotal-t.discount,q.currency)}</span></div>`:''}<div><span>Tax</span><span>${money(t.tax,q.currency)}</span></div><div><span>Total ${esc(q.currency)}</span><span>${money(t.total,q.currency)}</span></div></div><div class="paper-terms"><strong>Payment</strong> · ${esc(q.terms?.payment||'')}<br><strong>Delivery</strong> · ${esc(q.terms?.delivery||'')}<br>${esc(q.terms?.notes||'')}</div><div class="paper-footer"><span>${esc(q.company?.name||'')}</span><span>${esc(q.number)} · Customer copy</span></div></div>`;}
  function toast(message,error=false){if(error){const inline=document.getElementById(modal?.open?'modal-error':'quote-error');if(inline){inline.hidden=false;inline.textContent=message;}} const region=document.getElementById('toast-region');if(!region)return;const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.textContent=message;region.appendChild(el);setTimeout(()=>el.remove(),3200);}
  function audit(action,object,actor='Sarah Mitchell'){db.events.unshift({id:crypto.randomUUID(),action,object,at:new Date().toISOString(),actor});}
  function csvDownload(filename,rows){const csv=rows.map(row=>row.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();URL.revokeObjectURL(a.href);}
  function openCustomer(id){const c=db.customers.find(x=>x.id===id);if(!c)return;const qs=db.quotes.filter(q=>q.customerId===id);const won=currencyTotals(qs.filter(q=>['Accepted','Won'].includes(q.status)));showModal(c.name,`<div class="detail-kv"><div><span>Contact</span><strong>${esc(c.contact||'—')}</strong></div><div><span>Industry</span><strong>${esc(c.industry||'—')}</strong></div><div><span>Email</span><strong>${esc(c.email||'—')}</strong></div><div><span>Phone</span><strong>${esc(c.phone||'—')}</strong></div><div class="field full"><span>Address</span><strong>${esc(c.address||'—')}</strong></div><div class="field full"><span>Notes</span><strong>${esc(c.notes||'—')}</strong></div></div><hr style="border:0;border-top:1px solid var(--line);margin:17px 0"><div class="customer-stat"><span>Quotations</span><b>${qs.length}</b></div><div class="customer-stat"><span>Won value</span><b>${won}</b></div>${qs.length?`<div style="margin-top:12px">${qs.map(q=>`<div class="follow-row"><div class="follow-info"><strong>${esc(q.number)} · ${esc(q.title)}</strong><small>${badge(q.status)} &nbsp; ${money(quoteMath(q).total,q.currency)}</small></div><button class="btn" data-preview-quote="${q.id}">Open</button></div>`).join('')}</div>`:''}`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-new-quote-customer="${id}">New quote</button>`);}
  function openRfq(id){const r=getRFQ(id);if(!r)return;showModal(r.title,`<div class="detail-kv"><div><span>Request</span><strong>${esc(r.number)}</strong></div><div><span>Customer</span><strong>${esc(customerName(r.customerId))}</strong></div><div><span>Deadline</span><strong>${deadlineText(r.deadline,'Due')}</strong><small>${niceDate(r.deadline)}</small></div><div><span>Stage</span>${badge(r.status)}</div></div><section class="section-block"><h3>Original request & notes</h3><p class="request-copy">${esc(r.notes||'No original request text was recorded.')}</p></section><section class="section-block"><h3>Items to review</h3>${r.items?.length?r.items.map(i=>`<div class="task-row"><div><strong>${esc(i.name||i.description)}</strong><p>${esc(i.sourceText||i.description||'')}</p></div><span>${Number(i.qty??i.quantity)||0} ${esc(i.unit||'')}</span>${badge(i.catalogItemId?'Catalog match':'Needs review')}</div>`).join(''):'<p class="context-note">No extracted items yet. Add the requirements when you create the quote.</p>'}</section>`,`<button class="btn" data-edit-rfq="${esc(id)}">Edit request</button><button class="btn primary" data-convert-rfq="${esc(id)}">Create quotation →</button>`);}
  function addFollowupModal(){const quotes=db.quotes.filter(q=>!['Rejected','Expired'].includes(q.status));if(!quotes.length){toast('Create a quote before adding a follow-up.','error');return;}showModal('Add follow-up',`<form class="form-grid" id="follow-form">${field('Quotation','f-quote',quotes[0].id,'select',{options:quotes.map(q=>[q.id,`${q.number} · ${customerName(q.customerId)}`]),full:true})}${field('Task','f-title','Check in on quotation','text',{required:true,full:true})}${field('Due date','f-date',dateOffset(3),'date',{required:true,full:true})}${field('Note','f-note','','textarea',{full:true})}</form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-followup">Add follow-up</button>`);}
  async function aiDraft(){const c=getCustomer(quoteDraft.customerId),m=quoteMath(quoteDraft);let text=`Subject: Following up on ${quoteDraft.number}\n\nHello ${c?.contact||'there'},\n\nI wanted to check in on our quotation ${quoteDraft.number} for ${quoteDraft.title||'your request'}, totaling ${money(m.total,quoteDraft.currency)}. Please let me know if you would like any adjustments or have questions about the proposed scope.\n\nI’m happy to help.\n\nBest,\n${db.settings.company}`,label='Local template — edit before using';if(account){if(!quoteDraft.id){toast('Save the quote before generating an AI follow-up.','error');return;}try{const result=await api('/api/ai/follow-up',{method:'POST',body:JSON.stringify({quoteId:quoteDraft.id})});text=`Subject: ${result.draft.subject}\n\n${result.draft.body}\n\nSuggested timing: ${result.draft.recommendedTiming}`;label=result.label||'AI-generated — review before using';}catch(error){toast(error.message,'error');return;}}showModal('Follow-up draft',`<p style="font-size:13px;color:#788394;line-height:1.6">${esc(label)}</p><div class="field"><label for="follow-draft">Edit before using</label><textarea id="follow-draft" style="height:210px">${esc(text)}</textarea></div>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="copy-followup">Copy text</button>`);}
  async function aiProductDescription(){const description=document.getElementById('p-description')?.value.trim();if(!description){toast('Add a description before asking AI to improve it.','error');return;}try{const result=await api('/api/ai/generate-description',{method:'POST',body:JSON.stringify({name:document.getElementById('p-name')?.value,description,category:document.getElementById('p-category')?.value})});document.getElementById('p-description').value=result.description;toast('AI suggestion added. Review before saving.');}catch(error){toast(error.message,'error');}}
  async function aiSummarizeQuote(){const q=quoteDraft;if(!account||!q?.id){toast('Save the quote before asking for a summary.','error');return;}try{const result=await api('/api/ai/summarize-quote',{method:'POST',body:JSON.stringify({quoteId:q.id})});showModal('Quote summary',`<p style="font-size:13px;color:#788394">${esc(result.label||'AI-generated — review before using')}</p><div class="field"><label for="quote-summary">Salesperson summary</label><textarea id="quote-summary" style="height:220px">${esc(result.summary)}</textarea></div>`,'<button class="btn" data-action="close-modal">Close</button>');}catch(error){toast(error.message,'error');}}
  function parseItems(text){const lines=text.split(/\n|;|,(?=\s*\d)/).map(s=>s.trim()).filter(Boolean);return lines.map(line=>{const match=line.match(/(?:^|\b)(\d+(?:\.\d+)?)\s+(?:x\s*)?(.+)/i);if(!match)return null;const qty=+match[1],name=match[2].replace(/[.,]$/,'').trim();const p=db.products.find(x=>x.name.toLowerCase().includes(name.toLowerCase())||name.toLowerCase().includes(x.name.toLowerCase())||x.sku.toLowerCase()===name.toLowerCase());return p?itemFromProduct(p,qty):{name,sku:'',description:'Review and complete item details',qty,unit:'each',cost:0,price:0,tax:+db.settings.tax||0};}).filter(Boolean);}
  async function duplicateQuote(id){const source=getQuote(id);if(!source)return;const copy={...source,id:null,number:'',status:'Draft',created:dateOffset(0),expiry:dateOffset(+db.settings.validity||30),token:crypto.randomUUID(),publicUrl:null,acceptedAt:null,acceptedBy:null,rejectedAt:null,sourceQuoteId:source.id,items:source.items.map(item=>({...item,id:undefined}))};delete copy.version;delete copy.snapshot;try{if(account){const result=await api('/api/quotes',{method:'POST',body:JSON.stringify({...copy,sourceQuoteId:source.id})});Object.assign(copy,result.item);copy.sourceQuoteId=source.id;db.quotes.unshift(copy);}else{copy.id=crypto.randomUUID();copy.number='Q-DEMO-'+String(Date.now()).slice(-6);db.quotes.unshift(copy);audit('Quote duplicated',source.number);}save();toast('Quote duplicated as a new draft.');quotePreview(copy);}catch(error){toast(error.message,'error');}}  async function saveQuote(){const q=quoteDraft; q.title=document.getElementById('q-title').value.trim();q.customerId=document.getElementById('q-customer').value;q.currency=document.getElementById('q-currency').value;for(const line of q.items)line.currency=q.currency;q.created=document.getElementById('q-date').value;q.expiry=document.getElementById('q-expiry').value;q.payment=document.getElementById('q-payment').value.trim();q.delivery=document.getElementById('q-delivery').value.trim();q.discount=Math.max(0,+document.getElementById('q-discount').value||0);q.notes=document.getElementById('q-notes').value.trim();const inputs=document.querySelectorAll('[data-item]');for(const el of inputs){const i=q.items[+el.dataset.item],key=el.dataset.key;if(['qty','cost','price','tax'].includes(key))i[key]=Math.max(0,+el.value||0);else i[key]=el.value.trim();}if(!q.title||!q.customerId||!q.items.length||q.items.some(i=>!i.name||i.qty<=0)){toast('Add a title, customer and valid line items before saving.','error');return;}if(q.discount>q.items.reduce((a,i)=>a+i.qty*i.price,0)){toast('Discount cannot exceed the line subtotal.','error');return;}try{if(account){const result=await api('/api/quotes',{method:'POST',body:JSON.stringify(q)});Object.assign(q,result.item);delete q.token;const ix=db.quotes.findIndex(x=>x.id===q.id);if(ix>=0)db.quotes[ix]=q;else db.quotes.unshift(q);if(q.rfqId){const r=getRFQ(q.rfqId);if(r){r.status='Quoted';await api('/api/rfqs',{method:'POST',body:JSON.stringify(r)});}}}else{const existing=q.id?getQuote(q.id):null;if(existing){Object.assign(existing,q);audit('Quote edited',q.number);}else{q.id=crypto.randomUUID();db.quotes.unshift(q);audit('Quote created',q.number);if(q.rfqId){const r=getRFQ(q.rfqId);if(r)r.status='Quoted';}}save();}quoteDirty=false;toast('Quotation saved.');page='Quotations';quoteDraft=null;render();}catch(e){toast(e.message,'error');}}
