  async function uploadRfqAttachment(rfqId,file){const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer()),sha256=[...new Uint8Array(digest)].map(value=>value.toString(16).padStart(2,'0')).join(''),reservation=await api('/api/attachments/upload',{method:'POST',body:JSON.stringify({rfqId,fileName:file.name,mimeType:file.type,byteSize:file.size,sha256})});const uploaded=await fetch(reservation.uploadUrl,{method:'PUT',headers:{'content-type':file.type},body:file});if(!uploaded.ok)throw new Error('The RFQ was saved, but its attachment upload failed.');await api(`/api/attachments/${reservation.attachment.id}/complete`,{method:'POST',body:JSON.stringify({sha256})});}
