  function renderAIExtraction(extraction){window.__rfqAIResult=extraction;const target=document.getElementById('extraction-preview');if(!target)return;target.innerHTML=`<div class="panel" style="padding:12px"><div style="font-size:13px;font-weight:700;color:#2d5bdb">AI-generated — review before using</div><div class="field" style="margin-top:9px"><label for="ai-rfq-title">Suggested title</label><input id="ai-rfq-title" value="${esc(extraction.title||'')}"/></div>${extraction.summary?`<p style="font-size:13px;color:#687486">${esc(extraction.summary)}</p>`:''}${(extraction.missingInformation||[]).length?`<p style="font-size:13px;color:#a66a16"><b>Missing:</b> ${extraction.missingInformation.map(esc).join(' · ')}</p>`:''}${(extraction.warnings||[]).length?`<p style="font-size:13px;color:#a66a16"><b>Review:</b> ${extraction.warnings.map(esc).join(' · ')}</p>`:''}${(extraction.items||[]).map((item,index)=>`<div class="customer-stat" style="align-items:center;gap:7px;flex-wrap:wrap"><input data-ai-index="${index}" data-ai-field="name" aria-label="Item name" value="${esc(item.name)}" style="min-width:140px;flex:1"/><input data-ai-index="${index}" data-ai-field="quantity" type="number" min="0.0001" step="0.0001" aria-label="Quantity" value="${Number(item.quantity)||1}" style="width:80px"/><input data-ai-index="${index}" data-ai-field="unit" aria-label="Unit" value="${esc(item.unit)}" style="width:85px"/><select data-ai-index="${index}" data-ai-field="catalogItemId" aria-label="Catalog match"><option value="">Needs catalog match</option>${db.products.map(product=>`<option value="${esc(product.id)}" ${item.matchedCatalogItemId===product.id?'selected':''}>${esc(product.name)}${product.sku?` · ${esc(product.sku)}`:''}</option>`).join('')}</select><div style="flex-basis:100%;font-size:12px;color:#8993a1">${esc(item.sourceText||'')} · confidence ${Math.round((Number(item.confidence)||0)*100)}%</div><input data-ai-index="${index}" data-ai-field="description" aria-label="Description" value="${esc(item.description||item.notes||'')}" style="flex-basis:100%"/></div>`).join('')||'<p style="font-size:13px;color:#687486">No line items found. Add them manually after saving.</p>'}</div>`;}
  async function extractRfqAI(){const text=document.getElementById('rfq-text')?.value.trim();if(!text){toast('Paste the RFQ text first.','error');return;}const button=document.querySelector('[data-action="extract-rfq-ai"]');if(button){button.disabled=true;button.textContent='Extracting…';}try{const result=await api('/api/ai/extract-rfq',{method:'POST',body:JSON.stringify({text})});renderAIExtraction(result.extraction);}catch(error){toast(`${error.message} Use fallback extraction if needed.`,'error');}finally{if(button){button.disabled=false;button.innerHTML=`${icon('spark')} Extract with AI`;}}}
  async function saveImported(){const text=document.getElementById('rfq-text').value.trim();if(!text){toast('Paste RFQ content first.','error');return;}let items=parseItems(text);const aiResult=window.__rfqAIResult;let title=aiResult?.title||text.split(/[\n.]/)[0].slice(0,75)||'Imported customer request';if(aiResult){title=document.getElementById('ai-rfq-title')?.value.trim()||title;items=aiResult.items.map((item,index)=>{const values=[...document.querySelectorAll(`[data-ai-index="${index}"]`)],read=key=>values.find(input=>input.dataset.aiField===key)?.value;const match=db.products.find(product=>product.id===read('catalogItemId'));return{name:read('name')||item.name,sku:match?.sku||item.sku||'',description:read('description')||'',qty:Number(read('quantity'))||0,unit:read('unit')||'each',catalogItemId:match?.id||null,sourceText:item.sourceText,confidence:item.confidence};}).filter(item=>item.name&&item.qty>0);}const record={id:crypto.randomUUID(),number:`RFQ-${new Date().getFullYear()}-${String(db.rfqs.length+1).padStart(3,'0')}`,title,customerId:document.getElementById('import-customer').value,received:dateOffset(0),deadline:aiResult?.deadline||dateOffset(7),status:'New',priority:'Normal',source:aiResult?'AI-assisted capture':'Pasted text',notes:text,items};try{if(account){const result=await api('/api/rfqs',{method:'POST',body:JSON.stringify({...record,id:undefined})});Object.assign(record,result.item,{number:result.item.number||record.number});}db.rfqs.unshift(record);audit('RFQ imported',record.number);save();modal.close();toast(`RFQ created${items.length?` with ${items.length} reviewed item${items.length===1?'':'s'}`:''}.`);page='RFQs';render();window.__rfqAIResult=null;}catch(error){toast(error.message,'error');}}
  function acceptQuote(id){const q=getQuote(id);if(!q)return;const body=`<p style="font-size:13px;color:#657185;line-height:1.6">Confirm you agree to quotation ${esc(q.number)} and its stated terms.</p><form id="accept-form" class="form-grid">${field('Your name','a-name','','text',{required:true,full:true})}${field('Business email','a-email','','email',{required:true,full:true})}<label style="grid-column:1/-1;font-size:13px;color:#465267;display:flex;gap:8px;align-items:flex-start"><input id="a-agree" type="checkbox" style="margin:1px 0 0"/> I agree to the quotation and terms listed above.</label></form>`;showModal('Accept quotation',body,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-confirm-accept="${id}">Confirm acceptance</button>`);}
