  document.addEventListener('input',e=>{if(e.target.id==='table-search'){const q=e.target.value.toLowerCase();if(page==='RFQs')document.getElementById('rfq-table').innerHTML=rfqTable(db.rfqs.filter(r=>`${r.title} ${r.number} ${customerName(r.customerId)}`.toLowerCase().includes(q)&&(currentFilter==='All'||r.status===currentFilter)));if(page==='Quotations')document.getElementById('quote-table').innerHTML=quoteTable(db.quotes.filter(x=>`${x.title} ${x.number} ${customerName(x.customerId)}`.toLowerCase().includes(q)&&(currentFilter==='All'||x.status===currentFilter)));if(page==='Customers')document.getElementById('customer-table').innerHTML=customerRows(db.customers.filter(c=>`${c.name} ${c.contact} ${c.email}`.toLowerCase().includes(q)));if(page==='Products & services')document.getElementById('product-table').innerHTML=productRows(db.products.filter(p=>`${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(q)));}if(e.target.id==='global-query'){const q=e.target.value.toLowerCase();const hits=[...db.customers.filter(x=>`${x.name} ${x.contact}`.toLowerCase().includes(q)).map(x=>({type:'Customer',name:x.name,fn:()=>openCustomer(x.id)})),...db.quotes.filter(x=>`${x.title} ${x.number}`.toLowerCase().includes(q)).map(x=>({type:'Quote',name:`${x.number} · ${x.title}`,fn:()=>quotePreview(x)})),...db.rfqs.filter(x=>`${x.title} ${x.number}`.toLowerCase().includes(q)).map(x=>({type:'RFQ',name:x.title,fn:()=>openRfq(x.id)})),...db.products.filter(x=>`${x.name} ${x.sku}`.toLowerCase().includes(q)).map(x=>({type:'Item',name:x.name,fn:()=>addProductModal(x)}))].slice(0,8);document.getElementById('global-results').innerHTML=hits.map(h=>`<button class="btn" style="width:100%;justify-content:space-between;margin:3px 0" data-search-hit="${esc(h.type)}|${esc(h.name)}">${esc(h.name)}<span style="color:#929baa">${h.type}</span></button>`).join('')||'<span style="font-size:13px;color:#8993a1">No matches</span>';window.__searchHits=hits;}});
  document.addEventListener('change',async e=>{if(e.target.id==='status-filter'){currentFilter=e.target.value;render();}if(e.target.matches('[data-item]')&&quoteDraft){const el=e.target,i=quoteDraft.items[+el.dataset.item],key=el.dataset.key;i[key]=['qty','cost','price','tax'].includes(key)?Math.max(0,+el.value||0):el.value;updateCommercialPreview();}if(e.target.id==='csv-file'){const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){toast('CSV exceeds the 2 MB import limit.','error');e.target.value='';return;}const text=await file.text();const rows=parseCsv(text);window.__csvRows=rows;document.getElementById('csv-preview').innerHTML=`${Math.max(0,rows.length-1)} data rows found.<div style="margin-top:6px">${rows.slice(0,4).map(r=>esc(r.join(' · '))).join('<br>')}</div>`;}});
