  function parseCsv(text){const out=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))out.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(x=>x.trim()))out.push(row);return out;}
  async function importCsv(){if(account){toast('CSV import is available only in the fictional demo. Add production items through the catalog editor.','error');return;}const rows=window.__csvRows||[];if(rows.length<2){toast('Choose a CSV containing a heading row and data.','error');return;}const headers=rows[0].map(x=>x.trim().toLowerCase());const idx=(...names)=>headers.findIndex(h=>names.includes(h));const name=idx('name','product','item','service');if(name<0){toast('CSV needs a Name, Product, Item or Service heading.','error');return;}const sku=idx('sku','item code'),desc=idx('description'),cat=idx('category'),cost=idx('cost','cost price'),price=idx('price','selling price'),unit=idx('unit');let added=0,skipped=0;for(const row of rows.slice(1)){const n=row[name]?.trim();if(!n)continue;const code=sku>=0?row[sku]?.trim():'';if(code&&db.products.some(p=>p.sku.toLowerCase()===code.toLowerCase())){skipped++;continue;}db.products.push({id:crypto.randomUUID(),name:n,sku:code||'',description:desc>=0?row[desc]||'':'',category:cat>=0?row[cat]||'Imported':'Imported',cost:Math.max(0,parseFloat(cost>=0?row[cost]:'0')||0),price:Math.max(0,parseFloat(price>=0?row[price]:'0')||0),unit:unit>=0?row[unit]||'each':'each'});added++;}audit('Products imported',`${added} items`);save();modal.close();toast(`Imported ${added} items${skipped?`; skipped ${skipped} duplicate SKUs`:''}.`);page='Products & services';render();}
  async function saveSettings(){const updated=Object.assign({},db.settings,{company:document.getElementById('set-company').value.trim()||'Company',email:document.getElementById('set-email').value.trim(),phone:document.getElementById('set-phone').value.trim(),address:document.getElementById('set-address').value.trim(),currency:document.getElementById('set-currency').value,tax:Math.min(100,Math.max(0,+document.getElementById('set-tax').value||0)),margin:Math.min(100,Math.max(0,+document.getElementById('set-margin').value||0)),validity:Math.min(365,Math.max(1,+document.getElementById('set-validity').value||30)),payment:document.getElementById('set-payment').value.trim(),delivery:document.getElementById('set-delivery').value.trim(),template:document.getElementById('set-template').value});try{if(account){const result=await api('/api/settings',{method:'PUT',body:JSON.stringify(updated)});db.settings=result.settings;}else{db.settings=updated;audit('Settings updated','Company settings');save();}toast('Settings saved.');render();}catch(error){toast(error.message,'error');}}
  function renderLogin(){app.innerHTML=`<div class="login-wrap"><div class="login-card">${logo()}<div class="eyebrow" style="margin-top:18px">${account?'SIGNED-IN WORKSPACE':'ACCOUNT ACCESS'}</div><h1>${account?'Your workspace':'Work with your own data'}</h1><p>${account?`Signed in as ${esc(account.user.email)} · ${esc(account.role)}. Your records are saved to the server.`:'Create an organization or sign in. Demo records remain separate.'}</p>${account?`<button class="btn" data-action="signout">Sign out</button><button class="btn primary" data-action="enter-demo">Open workspace ${icon('arrow')}</button>`:`<div class="nav" style="grid-template-columns:1fr 1fr;margin-bottom:14px"><button class="active" data-auth-view="login">Sign in</button><button data-auth-view="signup">Create account</button></div><form id="auth-form"><div class="field"><label for="auth-email">Business email</label><input id="auth-email" type="email" required autocomplete="email"/></div><div class="field" id="org-field" style="display:none"><label for="auth-org">Organization name</label><input id="auth-org" autocomplete="organization"/></div><div class="field"><label for="auth-password">Password</label><input id="auth-password" type="password" minlength="12" required autocomplete="current-password"/><small style="font-size:12px;color:#8993a1">Use at least 12 characters.</small></div><button class="btn primary" id="auth-submit" type="submit">Sign in</button></form><button class="btn subtle" style="width:100%;margin-top:6px" data-action="forgot-password">Forgot password?</button><button class="btn" style="width:100%;margin-top:8px" data-action="enter-demo">Continue with fictional demo</button><div class="login-foot">Demo workspace and account records are separate.</div>`}</div></div>`;}
  function renderResetPassword(){const token=new URLSearchParams(location.search).get('token')||'';app.innerHTML=`<div class="login-wrap"><div class="login-card">${logo()}<h1>Reset your password</h1><p>Choose a new password with at least 12 characters.</p><form id="reset-form"><div class="field"><label for="reset-password">New password</label><input id="reset-password" type="password" minlength="12" maxlength="256" required autocomplete="new-password"/></div><div class="field"><label for="reset-confirm">Confirm password</label><input id="reset-confirm" type="password" minlength="12" maxlength="256" required autocomplete="new-password"/></div><button class="btn primary" type="submit">Update password</button><input id="reset-token" type="hidden" value="${esc(token)}"/></form></div></div>`;}
